-- 2904 🏋️ Exercises from the book "jurgen-klopp-102-passing-counter-pressing-possession-games-speed-warm-ups-direct" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'jurgen-klopp-102-passing-counter-pressing-possession-games-speed-warm-ups-direct');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Pre-match free warm-up and group passing', 'warm_up', 'unopposed', NULL, 14, 14, 'Liverpool Pre-Match Warm-up Part 1/6', 'Klopp (Liverpool)', 'Gentle individual start to a match-day warm-up, with and without the ball.', 'Whole warm-up laid out on one half before players arrive, including a 12 x 25 yard box on one side; 10 outfield starters spread over the half, keepers with GK coaches at goal.', 'Some players do their own activation work with or without a ball while others knock the ball around in small groups; keepers save shots from GK coaches.', NULL, NULL, NULL, '10 outfield + GKs', 10, NULL, 'half pitch incl. 12 x 25 yards box', NULL, NULL, 4.0, true, true, false, NULL, 10),
  ('Pre-match group activation circle', 'warm_up', 'unopposed', NULL, 15, 15, 'Liverpool Pre-Match Warm-up Part 2/6', 'Klopp (Liverpool)', 'Dynamic activation and stretching led by the fitness coach.', 'The 10 outfield players stand in a circle in midfield around the fitness coach; a coach lays balls out in the 12 x 25 box for later.', 'Fitness coach demonstrates and players copy dynamic moves (leg swings, high knees, heel flicks, quick moves out of the circle and back) plus some static stretches; keepers catch crosses.', NULL, NULL, NULL, '10 outfield + GKs', 10, NULL, NULL, NULL, NULL, 2.0, false, true, false, NULL, 20),
  ('Pre-match functional movements into sprints', 'warm_up', 'unopposed', NULL, 16, 16, 'Liverpool Pre-Match Warm-up Part 3/6', 'Klopp (Liverpool)', 'Raise intensity with movement patterns finished by sub-maximal sprints.', 'Players in pairs in two lines either side of a cone, fitness coach a few yards in front.', 'Pairs do a few yards of functional movement then sprint at about 80% to the coach, who steps back after each rep to lengthen the sprint; keepers save shots from the edge of the box.', NULL, 'Sprint distance grows each repetition.', NULL, '10 outfield in pairs', 10, NULL, NULL, NULL, NULL, 1.0, false, true, false, NULL, 30),
  ('Pre-match positional passing in pairs', 'passing_unopposed', 'unopposed', 'in_possession', 17, 17, 'Liverpool Pre-Match Warm-up Part 4/6', 'Klopp (Liverpool)', 'Sharpen passing and receiving with a position-matched partner.', 'Pairs across the width of the 12 x 25 yard box, partners matched by playing position.', 'Pairs mix one-touch passing, two-touch receive and pass, and receive-turn-manipulate-pass-back; keepers catch balls kicked into the six-yard box.', '1 touch, 2 touch and turn-and-return phases.', NULL, NULL, '5 pairs', 10, NULL, '12 x 25 yards', 22.9, 11.0, 2.0, false, false, false, NULL, 40),
  ('4v4+2 end-to-end keep-ball with counter-press', 'possession', 'opposed', 'to_defend', 18, 18, 'Liverpool Pre-Match Warm-up Part 5/6', 'Klopp (Liverpool)', 'Quick end-to-end circulation and instant counter-press on losing the ball.', '12 x 25 yard box, 4v4 inside with one neutral end player at each short end.', 'The team in possession moves the ball from one end player to the other; on a turnover the losing team switches straight away to pressing to win it back, and the new team has the same aim.', 'Mostly 1-2 touches.', NULL, 'Fast transition to defence after losing the ball.', '4v4+2', 10, 10, '12 x 25 yards', 22.9, 11.0, 3.0, false, false, true, NULL, 50),
  ('3-ball finishing drill and short sprints', 'finishing', 'unopposed', 'in_possession', 19, 19, 'Liverpool Pre-Match Warm-up Part 6/6', 'Klopp (Liverpool)', 'Get every player several quick finishes before kick-off.', 'Full backs wide with a coach; other 8 outfield players in 3 central stations outside the box; keeper in goal.', 'Central player dribbles off a cone and shoots, then receives a lay-off, turns and shoots again; coach plays a ball down the line for the full back to cross and the central player attacks the cross for a third finish.', '3 consecutive shots per central player.', NULL, NULL, '10 outfield + GK', 10, NULL, 'edge of box and wings', NULL, NULL, 4.0, true, true, true, NULL, 60),
  ('Receive, turn, feint and dribble end to end', 'technical', 'unopposed', 'in_possession', 21, 21, 'Pre-season Training 1', 'Klopp (Liverpool)', 'Receive on the half-turn, drive forward and beat a mannequin with a feint.', 'Rectangle with mannequins scattered as defenders; a player at each end and a working player in the middle.', 'Middle player checks away then shows between two mannequins, receives, turns and carries forward, feints past a mannequin and passes to the far end (coach), then repeats the other way.', NULL, NULL, 'Switch roles after a few reps.', '3 per station', 2, 3, NULL, NULL, NULL, NULL, false, false, true, NULL, 70),
  ('3 v middle runner race to mini goals', 'passing_opposed', 'passive', 'in_possession', 22, 22, 'Pre-season Training 2', 'Klopp (Liverpool)', 'Move the ball quickly side to side to score before the middle player reacts.', 'Square with a mini goal at each end beside a mannequin; one middle player in a bib in the centre, 3 reds around the outside.', 'Middle player dribbles in from a cone and passes to a red; the reds pass quickly to try to score in a mini goal before the middle player can touch the mannequin beside that goal.', 'Goal only counts if scored before the middle player touches that side''s mannequin.', NULL, 'Middle player must track the ball constantly; change the middle player often.', '3+1', 4, 4, NULL, NULL, NULL, NULL, true, false, true, NULL, 80),
  ('Juggle, collect bibs and race to score', 'warm_up', 'unopposed', NULL, 23, 23, 'Pre-season Training 3', 'Klopp (Liverpool)', 'Reaction, speed and finishing in a fun race between stations.', 'Side-by-side boxes, each with coloured bibs on the sides, two mannequins and a mini goal.', 'Players juggle; the coach calls 1-4 colours, players leave the ball, collect those bibs in order, then get the ball and dribble up to shoot past the mannequins into the mini goal.', 'First to score beats the neighbouring station.', 'Some players carry the ball while collecting bibs instead of leaving it.', NULL, '1 per station, several stations', 2, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 90),
  ('Double triangle pass and dribble circuit', 'passing_unopposed', 'unopposed', 'in_possession', 24, 24, 'Pre-season Training 4', 'Klopp (Liverpool)', 'Simple quick passing with angled receiving, run in two mirrored triangles.', 'Two mirrored triangles: A players at the bottom, B players wide by poles, C players at the top by poles.', 'A passes diagonally to B who checks off his pole; B passes diagonally to C who comes forward off his pole; C dribbles diagonally across and passes to the waiting player in the opposite group. Rotate A to B to C to opposite group.', 'B plays 2 touch.', NULL, 'Speed, simple passes.', 'about 8-10', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 100),
  ('Double triangle one-twos on the run', 'passing_unopposed', 'unopposed', 'in_possession', 25, 25, 'Pre-season Training 5', 'Klopp (Liverpool)', 'One-touch combination play and timed forward runs.', 'Same mirrored double triangle with poles as Practice 4.', 'A to B (drops off pole); B to C, C sets back for B''s one-two, B plays C round the pole, C plays inside for A''s forward run, A returns a one-two, C passes to the opposite group. Rotate A to B to C to opposite group.', 'All one touch.', NULL, NULL, 'about 8-10', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Pass, move, dribble poles, target goal', 'passing_unopposed', 'unopposed', 'in_possession', 26, 26, 'Pre-season Training 6', 'Klopp (Liverpool)', 'Checking runs, timed diagonal pass, dribble and finish into a small goal.', 'Rectangle with A at one corner, B and C along the far side, a row of poles outside one end and a target goal at the end.', 'A plays to C who checked away, C plays across to B who checked, B sets back for A, A plays a diagonal for C running round B''s cone; C dribbles through the poles and passes into the goal. Rotate A to B to C to A.', 'Next A starts as soon as C shoots.', NULL, NULL, '4+', 4, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 120),
  ('One-two circuit into target goal', 'passing_unopposed', 'unopposed', 'in_possession', 27, 27, 'Pre-season Training 7', 'Klopp (Liverpool)', 'Passing circuit with one-twos, third runs and a finish, both sides.', 'Big area with two mini goals at one end, mannequins on each wing, players A, B, C and C2 positioned around cones.', 'A and B play a one-two, A plays diagonally to C who checks back, C sets for B on the run, B plays diagonally to C2 in front of the mannequin, C2 plays C in, C feeds C2 running round the mannequin and C2 scores in the mini goal. Rotate A to B to C to C2 to A.', NULL, 'Run from either side.', NULL, '6+', 5, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 130),
  ('Attacking combinations in threes on signal', 'combination', 'unopposed', 'in_possession', 28, 28, 'Pre-season Training 8', 'Klopp (Liverpool)', 'Read a signal and run rehearsed three-man combinations to finish.', 'Around the D: coloured mannequins (yellow, blue, red, orange), two mini goals on the 6-yard line, A with balls at the centre circle edge.', 'Coach calls a colour, B runs to that mannequin to receive A''s first pass, then A, B and C play a set combination ending with a shot in one of the mini goals.', NULL, 'Different combination per colour; three variations shown.', NULL, '3 per group', 3, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 140),
  ('Mobility circuit with stretching and agility (1)', 'warm_up', 'unopposed', NULL, 30, 30, 'Warm-up Without a Ball 1', 'Klopp (Liverpool)', 'Progressive mobility, stretching and speed/agility work.', '4 lanes of yellow and white cones with groups at each; stretching area alongside; 4 agility stations beyond (hurdles, side-step markers, poles).', '1-4 min: movement drills cone to cone with jog back; 4-7 min: static then pair dynamic stretching; 7-10 min: quicker moves (sideways and back, jump-turn-go, fake and go); 10-12 min: groups go through all 4 agility stations.', NULL, NULL, NULL, '4 groups', 8, NULL, NULL, NULL, NULL, 12.0, false, false, false, NULL, 150),
  ('Mobility circuit with stretching and agility (2)', 'warm_up', 'unopposed', NULL, 31, 31, 'Warm-up Without a Ball 2', 'Klopp (Liverpool)', 'Mobility, dynamic stretches and agility stations.', '4 lanes with white and yellow cones; 4 stations A-D beyond with ladders, hoops and markers.', '1-3 min movement drills between white cones; 3-7 min dynamic stretches on the move (quads, squats, lunges); 7-10 min static and dynamic stretching; 10-13 min rotate through the 4 speed/agility stations.', NULL, NULL, NULL, '4 groups', 8, NULL, NULL, NULL, NULL, 13.0, false, false, false, NULL, 160),
  ('Speed warm-up circuit with static stretching', 'warm_up', 'unopposed', NULL, 32, 32, 'Warm-up Without a Ball 3', 'Klopp (Liverpool)', 'Warm-up building to higher-speed movement and a sprint finish.', 'Lanes of yellow and red cones, static stretching areas at each end, ground markers and poles for the progression.', '1-5 min movement drills with stretch pauses; 5-8 min static stretching; 8-10 min faster moves (forward/back, jump to head and accelerate).', NULL, '10-12 min: quick forward steps (A) or lateral steps (B) through markers then sprint round poles to the diagonally opposite group.', NULL, '4 groups', 8, NULL, NULL, NULL, NULL, 12.0, false, false, false, NULL, 170),
  ('Quick feet speed warm-up with physical duel', 'warm_up', 'unopposed', NULL, 33, 33, 'Warm-up Without a Ball 4', 'Klopp (Liverpool)', 'Speed and coordination, including shoulder-to-shoulder contact.', 'Two lanes between blue cones with small cone groups in the middle; groups start at each end.', 'Part 1 (10 min): full movement routine plus stretching. Part 2 (4 min): sprint and lateral steps over cones and back, sprint with quick feet round cones, shoulder duel with the player from the opposite line, half-pace back.', NULL, 'Lateral right to red cone, lateral left.', NULL, '4 groups', 8, NULL, NULL, NULL, NULL, 14.0, false, false, false, NULL, 180),
  ('Coordination jumps and movements warm-up', 'warm_up', 'unopposed', NULL, 34, 34, 'Warm-up Without a Ball 5', 'Klopp (Liverpool)', 'Footwork and jumping coordination finished with sprints.', '3 lanes, each with 6 cones and a 4-pole square roped 5-8 cm off the ground.', '1-4 min: quick steps in and out of cones, two-foot jump into the square with 1-second pauses; 5-8 min: lateral steps, one-foot jump in and out, sprint; 8-12 min: two lateral steps between cones, two left-foot touches in the square, sprint. Walk back.', NULL, 'Alternate sides each repetition.', NULL, '3 groups', 6, NULL, NULL, NULL, NULL, 12.0, false, false, false, NULL, 190),
  ('Dynamic obstacle circuit with mixed movements', 'warm_up', 'unopposed', NULL, 35, 35, 'Warm-up Without a Ball 6', 'Klopp (Liverpool)', 'Lap circuit of varied movements over cones, hurdles and mannequins.', 'Two identical circuits side by side, groups of 5 starting in each corner; large cones, small cones, mannequins, hurdles of rising height.', 'Sideways through large cones, side-steps over cones, jump and head gesture at mannequins left and right, run, lateral steps, side-steps, hop over 3 hurdles, repeat.', NULL, '2 laps moderate pace, then 2 faster laps with varied exercises.', NULL, '20+ in groups of 5', 20, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 200),
  ('Ball control warm-up with stations', 'warm_up', 'unopposed', NULL, 37, 37, 'Warm-up With a Ball 1', 'Klopp (Liverpool)', 'Technical and agility actions with the ball while moving freely.', 'Area with stations: 4 poles, 4 small cones, 2 large cones, 2 crossed poles, 2 hurdles; every player has a ball.', 'Players roam: dribble through poles, leave ball for lateral steps over cones and return, dribble between large cones, pass through crossed poles and run round, leave ball for lateral jumps over hurdles and back.', NULL, NULL, NULL, 'squad', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 210),
  ('Speed of movement with volleys and headers', 'warm_up', 'unopposed', NULL, 38, 38, 'Warm-up With a Ball 2', 'Klopp (Liverpool)', 'Quick feet plus volley/header returns to a server.', 'Lanes with 3 cones each side and a coach with balls in the middle; groups A-F start at both ends.', 'Quick forward and back steps through cones, move forward and volley a thrown ball back to the coach''s hands, run round the end pole and join the next group; repeat in the other direction.', NULL, 'Coach changes the action each round, e.g. headers.', NULL, '6 groups', 12, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 220),
  ('Movement and one-twos warm-up circuit', 'warm_up', 'unopposed', NULL, 39, 39, 'Warm-up With a Ball 3', 'Klopp (Liverpool)', 'Mix of dynamic movement, ball touches and one-twos with a coach.', 'Lanes with poles, a mannequin with a coach feeding, 4 lateral cones and a pole at the end; points A, B, C.', 'Leg kicks through poles, quick inside-foot touches, jog to mannequin for two one-twos with the coach, jog on, lateral steps through cones, repeat, then backward/forward runs round poles and back to A.', NULL, 'Coach varies the action each round, e.g. volleys.', NULL, 'squad in groups', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 230),
  ('Team warm-up race: speed, pass, shoot', 'warm_up', 'unopposed', NULL, 40, 40, 'Warm-up With a Ball 4', 'Klopp (Liverpool)', 'Competitive warm-up ending in a race to finish.', '3 groups in lanes with poles, rebounders and mini goals at the far end.', 'Stage 1: movement routine without ball. Stage 2: dribble with moves to a cone, turn and pass to the next player (2 reps). Stage 3: on ''Go'' sprint to put a cone on a pole, play off the rebounder, receive, turn and score in a mini goal.', 'First to score earns a point for the team.', NULL, NULL, '3 groups of 4', 9, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 240),
  ('Juggling relay in singles, pairs, fours', 'warm_up', 'unopposed', NULL, 41, 41, 'Warm-up With a Ball 5', 'Klopp (Liverpool)', 'Ball mastery under competitive pressure.', 'Teams of 8 split at both ends of lanes with a bin in the middle.', 'Round 1: one player juggles up to the bin and tries to drop the ball in; a ground touch sends him back to start; the next player goes from the other end. Round 2: in pairs. Round 3: in fours.', 'Pairs and fours limited to one touch each; first team done wins, losers do push-ups.', 'Singles, then pairs, then fours.', NULL, 'teams of 8', 16, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 250),
  ('Football tennis 5v5, 3 touches', 'warm_up', 'opposed', NULL, 42, 42, 'Warm-up With a Ball 6', 'Klopp (Liverpool)', 'Fun competitive touch and volleying game.', 'About 5 x 15 yards split by a net, 5 per side.', 'Server drops the ball from his hands and volleys it over; receivers have up to 3 team touches, one per player, with one bounce allowed before returning it.', 'Point won if opponents let it bounce twice, take too many touches, hit the net or play it out.', NULL, 'Have fun and celebrate points.', '5v5', 10, 10, '5 x 15 yards', 13.7, 4.6, NULL, false, false, false, NULL, 260),
  ('Double triangle 2-touch passing warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 43, 43, 'Warm-up With a Ball 7', 'Klopp (Liverpool)', 'Two-touch passing with checking movement in a connected circuit.', 'Two connected triangles with corner players A-H and middle players C/G; two balls start from A and E.', 'A/E pass to B/F, B/F play diagonally into C/G who check away first, C/G pass diagonally on, and play keeps going clockwise; players follow their pass.', '2 touch; direction changes every 3 minutes.', 'C/G set the ball back for B/F to complete a one-two, then B/F pass to D/H.', NULL, 'about 10-12', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 270),
  ('Colour call quick feet sprint race', 'conditioning', 'unopposed', NULL, 45, 45, 'Speed & Agility 1', 'Klopp (Liverpool)', 'Reaction to a signal plus quick feet and sprinting.', '4 lines of players; each lane has red and yellow cone pairs and a white finish cone.', 'Coach calls Red or Yellow; first players side-step over that pair, sprint to the matching cone, side-step over it and the next cone, then sprint past the white finish cone.', 'Fastest wins.', NULL, NULL, '4 groups', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 280),
  ('Left-or-right drop back sprint race', 'conditioning', 'unopposed', NULL, 46, 46, 'Speed & Agility 2', 'Klopp (Liverpool)', 'React to a direction call, backpedal and sprint.', 'Groups in lanes, each player starting at a white cone with two poles behind and a white finish cone ahead.', 'Players bounce on their toes; coach calls Left or Right, they move backwards through the poles and round the named pole then sprint past the finish cone.', 'Fastest wins.', NULL, 'Stay on the balls of the feet ready to react.', '5 groups', 10, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 290),
  ('Multiple-signal speed of movement race', 'conditioning', 'unopposed', NULL, 47, 47, 'Speed & Agility 3', 'Klopp (Liverpool)', 'React to a chain of calls with side-steps and sprints.', 'Lanes about 12 yards with a middle cone, left/right cones, and white (forward) and blue (back) finish cones.', 'On Go sprint to the middle cone; on Right/Left side-step that way and return (twice); then on Forward or Back sprint to the white or blue cone.', 'Fastest wins.', NULL, NULL, '4 groups', 8, NULL, '12 yards lanes', 11.0, NULL, NULL, false, false, false, NULL, 300),
  ('Side-to-side mannequin switch sprint race', 'conditioning', 'unopposed', NULL, 48, 48, 'Speed & Agility 4', 'Klopp (Liverpool)', 'Fast reactions, switching sides and turning to sprint.', '4 lines facing a central zone with two pairs of mannequins; players start at cones.', 'On Go each first player sprints to the mannequin on his side and bounces; coach calls Change 0-2 times to switch players to the other mannequin, then Go and all four turn and sprint back to the start.', 'Fastest wins; avoid collisions when switching.', NULL, NULL, '4 groups', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 310),
  ('Side-to-side signal reactions sprint race', 'conditioning', 'unopposed', NULL, 49, 49, 'Speed & Agility 5', 'Klopp (Liverpool)', 'Reaction speed to sound and visual cues, lateral movement and sprinting.', 'Rectangle with two yellow mannequins in the middle, a blue mannequin on each side, red cones at the back end and blue cones at the far end; two lines of players at the back.', 'Front pair stand bouncing at the middle mannequins; coach calls left or right (once or twice) and both shuffle to touch that side''s mannequin and come back to the middle. Coach then either shouts back (sprint back to red cones) or bounces the ball (sprint forward past blue cones).', 'Fastest player wins; next pair steps in.', NULL, 'Stay on the balls of the feet; react to the signal, not the opponent.', 'Pairs from two lines', 2, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 320),
  ('Turn-and-go reaction sprint race', 'conditioning', 'unopposed', NULL, 50, 50, 'Speed & Agility 6', 'Klopp (Liverpool)', 'Fast turns, awareness and changes of direction with a sprint finish.', 'Two large lanes between red cones (start) and blue cones (far end) with yellow mannequins in the middle; players side-on in two groups.', 'On ''turn'' (usually twice) the pair spin 180 degrees; on ''go'' they sprint to the mannequin; on ''back'' they turn and race back to the red cones.', 'Fastest wins. If the coach bounces the ball after any turn/go call, players must keep sprinting forward to the blue cone instead of turning back.', NULL, 'Stay alert - the ball bounce is a trap for players anticipating ''back''.', 'Pairs from two groups', 2, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 330),
  ('Colour-call 1v1 sprint duel', 'conditioning', 'unopposed', NULL, 51, 51, 'Speed & Agility 7', 'Klopp (Liverpool)', 'Reaction to a colour signal and acceleration over a short distance in a 1v1 race.', 'Short strip (about 5 yards each way from centre) with two red poles at one end and two yellow poles at the other; players in pairs at either end.', 'One player from each end jogs to a centre cone facing each other and bounces on the spot; coach calls a colour and both race through the poles of that colour.', 'First through the poles wins; next pair enters.', NULL, 'React instantly, first steps explosive.', 'Pairs', 2, NULL, 'about 5 yds each side of centre', NULL, NULL, NULL, false, false, false, NULL, 340),
  ('Shoulder duel then signal sprint race', 'conditioning', 'opposed', NULL, 52, 52, 'Speed & Agility 8', 'Klopp (Liverpool)', 'Physical contact followed by a fast reaction and sprint.', 'Short strip with poles at both ends (about 5 yards from centre); players in two lines one behind the other at one end.', 'One player from each group jogs into the centre side-on and they go shoulder to shoulder at about half effort; coach calls back or forward and both turn and sprint through the matching poles.', 'First through the poles wins; next pair enters.', NULL, 'Controlled 50% duel, then switch instantly to the sprint.', 'Pairs', 2, NULL, 'about 5 yds each side of centre', NULL, NULL, NULL, false, false, false, NULL, 350),
  ('Quick turns, colour touch, race to finish', 'conditioning', 'unopposed', NULL, 53, 53, 'Speed & Agility 9', 'Klopp (Liverpool)', 'Turning speed, colour recognition and racing to a finish line.', 'Area about 25 yards long with a yellow and red mannequin at each side and finish lines at each end; players face each other from either side.', 'Coach calls turn (180 degrees) twice, then a colour; both sprint to touch that colour mannequin, then turn and race to the opposite finish line.', 'Fastest wins; next pair.', 'Started simply with sprinting to touch mannequins then the finish; turns added as a progression.', NULL, 'Pairs', 2, NULL, '25 yds', 22.9, NULL, NULL, false, false, false, NULL, 360),
  ('Rotate partners then signal sprint race', 'conditioning', 'unopposed', NULL, 54, 54, 'Speed & Agility 10', 'Klopp (Liverpool)', 'Reaction to left/right and colour calls, rotation and sprinting.', 'Area about 12 yards with start cones either side, a red pair and a yellow pair of poles at different ends; players start facing away from each other.', 'Coach calls left or right and both sprint around that cone to meet in the middle, holding each other''s arms; on ''change'' they rotate 180 degrees together; on a colour call they release and sprint through those poles.', 'Fastest wins; next pair.', NULL, NULL, 'Pairs', 2, NULL, '12 yds', 11.0, NULL, NULL, false, false, false, NULL, 370),
  ('Spin holding arms, colour race to finish', 'conditioning', 'unopposed', NULL, 55, 55, 'Speed & Agility 11', 'Klopp (Liverpool)', 'Reacting to a colour call while disorientated by rotations.', 'Area about 12 yards with a middle cone and white and red cones at each end; two groups facing.', 'On ''go'' one from each group sprints to the middle cone and they hold arms; each ''change'' call (0, 1 or 2 times) they rotate 180 degrees clockwise; coach calls white or red and they race past that colour''s cones.', 'Fastest wins. Coach can call the colour at any time, even mid-rotation.', 'Extra command: on left or right the players balance on one leg.', NULL, 'Pairs', 2, NULL, '12 yds', 11.0, NULL, NULL, false, false, false, NULL, 380),
  ('Side-step, hurdle balance, signal sprint race', 'conditioning', 'unopposed', NULL, 56, 56, 'Speed & Agility 12', 'Klopp (Liverpool)', 'Coordination, agility and balance combined with a signalled sprint.', 'Area about 12 yards wide with ground poles, a hurdle and a blue cone near each start; two groups facing each other.', 'Players face each other; on ''go'' they side-step over the floor poles and the hurdle and hold a one-leg balance; on the next ''go'' they side-step back, turn around the blue cone and sprint to the far end.', 'Fastest wins.', NULL, 'Hold the balance still until the signal.', 'Pairs', 2, NULL, '12 yds', 11.0, NULL, NULL, false, false, false, NULL, 390),
  ('Three-station coordination and sprint circuit', 'conditioning', 'unopposed', NULL, 57, 57, 'Speed & Agility 13', 'Klopp (Liverpool)', 'Speed, coordination and agility through three short stations ending in sprints.', 'Three parallel stations about 15 yards long: rings and hurdles with mannequins; speed rings and a blue cone; speed ladder and poles.', 'Groups rotate: (1) one foot in a ring and one over a hurdle with a short pause, then sprint around a mannequin; (2) fast one-footed steps through rings then sprint past the cone; (3) lateral steps through the ladder, diagonal sprint past a pole and return round the other pole.', NULL, NULL, NULL, 'Groups', NULL, NULL, 'about 15 yds per station', 13.7, NULL, NULL, false, false, false, NULL, 400),
  ('Quick steps, fake and diagonal sprint lanes', 'conditioning', 'unopposed', NULL, 58, 58, 'Speed & Agility 14', 'Klopp (Liverpool)', 'Quick feet, changes of direction and short sprints.', 'Two lanes about 10 yards long, each with 4 small cones and two poles; groups at each end.', 'Lane 1: forward quick steps through the cones, fake step, sprint round the first pole and cut diagonally around the next, join the opposite line. Lane 2: same with lateral steps.', NULL, NULL, NULL, 'Groups', NULL, NULL, '10 yds', 9.1, NULL, NULL, false, false, false, NULL, 410),
  ('Four-station plyometric and slalom circuit', 'conditioning', 'unopposed', NULL, 59, 59, 'Speed & Agility 15', 'Klopp (Liverpool)', 'Quick steps, hops, slalom and agility in a continuous circuit.', 'Four stations A-D side by side: cones and hurdle, cones, 6 poles, two speed ladders.', 'A: hop over cones and hurdle landing on the other foot, both sides. B: quick forward steps with a step over each red cone. C: slalom the poles. D: quick steps through the ladders, jog back to A.', NULL, 'After each round the coach varies it, e.g. lateral movement in B and D, backwards in C.', NULL, 'Whole squad', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 420),
  ('Plyometric agility circuit for explosiveness', 'conditioning', 'unopposed', NULL, 60, 60, 'Speed & Agility 16', 'Klopp (Liverpool)', 'Explosive power and agility via hops, hurdles, hoops and skips.', 'Four stations A-D: cones for skips, hurdles with hoops and large cones, a line of 10 cones, ground pole with hoops.', 'A: jog and high knee skips between cones. B: single-leg hops over hurdles into hoops, side-step the cones, repeat on the other leg. C: lateral steps leading with each foot. D: single-leg hops over a ground pole into hoops, half-pace run, jog back to A.', NULL, 'After each round the coaches vary it, e.g. moving backwards in B.', NULL, 'Whole squad', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 430),
  ('Fast feet, hops and jumps speed circuit', 'conditioning', 'unopposed', NULL, 61, 61, 'Speed & Agility 17', 'Klopp (Liverpool)', 'Fast feet, plyometric hops, jumps and sprints in a loop.', 'Oval circuit with hurdles and cones, a cone slalom, mini hurdles, a pole and a speed ladder.', 'Hop over hurdle and cone right-to-left foot, then left-to-right; quick steps through cones with changes of direction; jog; two-footed jumps over 4 hurdles; run round a pole; ladder; jog back and repeat the opposite way.', NULL, 'Coach adds isolated short sharp steps between cones with a 1-second pause then accelerate.', NULL, 'Whole squad', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 440),
  ('Three-player one-two end to end', 'passing_unopposed', 'unopposed', 'in_possession', 64, 64, 'Passing Combinations 1', 'Klopp (Liverpool)', 'One-twos, support angles and checking away before receiving.', 'Long narrow channel with three players A, B, C; A and B at one end, C at the other.', 'A passes to B, gets the return to move onto (one-two); B moves to A''s spot; the ball goes long to C, who checked away. A runs up diagonally to support C, sets back, and the pattern repeats end to end.', 'All one touch.', NULL, 'Check away before showing; diagonal support angle.', '3', 3, 3, NULL, NULL, NULL, NULL, false, false, true, NULL, 450),
  ('Four-player support combination, follow pass', 'passing_unopposed', 'unopposed', 'in_possession', 65, 65, 'Passing Combinations 2', 'Klopp (Liverpool)', 'Support angles and passing inside for a teammate to move onto.', 'Narrow channel with cones at each end, two players at each end.', 'A passes to B who comes off the cone; B lays wide for A who moved diagonally; A passes inside for B to run onto; B plays long to C, and C, D repeat the same at the other end. Players follow their pass.', 'All one touch.', NULL, 'Diagonal movement to give a good angle.', '4+', 4, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 460),
  ('Lofted passing in two pairs', 'passing_unopposed', 'unopposed', 'in_possession', 66, 66, 'Passing Combinations 3', 'Klopp (Liverpool)', 'Long lofted passing, receiving on the half-turn and lay-offs.', 'Two pairs (A/B and C/D) far apart.', 'A passes to B who checks away and receives on the half-turn, B lofts to C; C plays to D (1-2 touches), D lays off and C lofts back to B; continues with pairs swapping roles.', '1-2 touches for receivers; partners swap positions after each lofted pass.', NULL, 'Receive on the half-turn to open up for the long ball.', '4', 4, 4, NULL, NULL, NULL, NULL, false, false, true, NULL, 470),
  ('Passing in fours, switch to go in behind', 'passing_unopposed', 'unopposed', 'in_possession', 67, 67, 'Passing Combinations 4', 'Klopp (Liverpool)', 'Thinking as a group: recognise a forward run and switch the play to find it.', 'Several groups of 4 across a full pitch.', 'Four players pass freely among themselves; when one makes a forward run (the trigger), the ball is set back and a teammate plays a ground or lofted pass in behind; all four break forward towards the other end and continue.', NULL, NULL, 'Change direction together; play forward on the trigger.', 'Groups of 4', 4, NULL, 'Full pitch', NULL, NULL, NULL, false, false, true, NULL, 480),
  ('Two-touch outside-the-cone triangle', 'passing_unopposed', 'unopposed', 'in_possession', 68, 68, 'Passing Combinations 5', 'Klopp (Liverpool)', 'Two-touch receiving and passing with check-away movement.', 'Large triangle of cones with players at each corner (two at the start).', 'A passes to B, who checks away then opens to receive outside the cone; B passes to C, C to D likewise; players follow their pass and it continues anti-clockwise.', 'Two touches.', NULL, 'Check away, open up, receive outside the cone.', '4+', 4, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 490),
  ('Triangle one-twos with timed support', 'passing_unopposed', 'unopposed', 'in_possession', 69, 69, 'Passing Combinations 6', 'Klopp (Liverpool)', 'Timing of support runs and one-twos around a triangle.', 'Triangle with players at each corner.', 'A passes to B who checks away and shows; B gives back for A to run onto; A plays B around the cone; B passes to C and repeats; continues anti-clockwise with players following their pass.', NULL, NULL, 'Time the move to arrive as the ball arrives.', '4+', 4, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 500),
  ('Triangle central support, diagonal pass, dribble', 'passing_unopposed', 'unopposed', 'in_possession', 70, 70, 'Passing Combinations 7', 'Klopp (Liverpool)', 'Central support play, diagonal passing and receiving behind poles then dribbling.', 'Triangle with a start position A, a central cone for B and two wide positions C1, C2 behind pairs of poles.', 'A1 to B1 on the half-turn, B1 to C1 who opens up behind the poles and dribbles back to start; as soon as C1 receives, A2 plays a second ball to A1, who goes to C2 on the other side, who also dribbles back.', NULL, NULL, 'Good technique, right speed and direction of pass.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 510),
  ('Double triangle passing Y with mannequin', 'passing_unopposed', 'unopposed', 'in_possession', 71, 71, 'Passing Combinations 8', 'Klopp (Liverpool)', 'Link and support play: drop and show, diagonal passing.', 'Y shape: A at the base, B by a central mannequin, C and D at the two top corners.', 'A to B who drops around the mannequin; B back to A who moves to an angle; A diagonal to C; C to B moving round the mannequin; B diagonal to D; D to the next A. Players rotate A to B to C to D.', NULL, 'Play clockwise and anti-clockwise.', 'The quicker the support, the easier the pass.', '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 520),
  ('Two-ball passing diamond with press', 'passing_opposed', 'passive', 'in_possession', 72, 72, 'Passing Combinations 9', 'Klopp (Liverpool)', 'One-touch passing in a diamond while the passer presses the receiver.', 'Diamond with A1/A2, B, C1/C2 and D on the corners; two balls start at A1 and C1.', 'A1/C1 pass to B/D and follow to press; B/D touch forward and go round the presser, then pass to C2/A2 and press them; C2/A2 pass on to the next players. Rotation A-B-C2-C1-D-A2-A1, anti-clockwise.', 'One touch, move around the pressing player.', NULL, NULL, '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 530),
  ('One-twos and third-man run with switch', 'passing_unopposed', 'unopposed', 'in_possession', 73, 73, 'Passing Combinations 10', 'Klopp (Liverpool)', 'Lay-offs, third-man runs and switching play, all one touch.', 'Diamond-like set-up with mannequins and pole gates; players at A (start), B, C, D and E positions.', 'A to B who checks then drops; B lays off for A; A to C dropping in front of a mannequin; C passes inside for B''s run; B to D who checks and runs across round two poles; D lays off for C round the mannequin; C plays the final pass for E running beyond the mannequin; E dribbles through a pole gate back to start.', 'One touch throughout; players rotate A to B to C to D to E to A.', NULL, 'Check away before every receive.', '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 540),
  ('Third-man runs and give-and-go circuit', 'passing_unopposed', 'unopposed', 'in_possession', 74, 74, 'Passing Combinations 11', 'Klopp (Liverpool)', 'Third-man combinations and give-and-gos linking into a mirrored circuit.', 'Diamond with mannequins at two corners; two mirrored set-ups side by side.', 'A to B off the cone, B lays off for A''s forward run; A to C in front of the mannequin; C lays off for B who drops and runs round the cone; B across to D; D lays off for C round two mannequins; C plays the final ball for D''s run round the mannequins; D dribbles to the mirrored set-up, which runs clockwise.', 'One touch throughout; players rotate positions into the mirrored group.', NULL, NULL, '8+ (two groups)', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 550),
  ('Two-touch double triangle passing circuit', 'passing_unopposed', 'unopposed', 'in_possession', 75, 75, 'Passing Combinations 12', 'Klopp (Liverpool)', 'Two-touch receiving on the half-turn in a two-ball double triangle.', 'Two triangles joined at a central point (bow-tie): A/H and F at the bottom corners, B and D/E at the top, C/G in the centre.', 'Two balls start at A and E. A/E pass to B/F who open up and receive; B/F pass diagonally to C/G who check and open up; C/G pass to D/H to complete. Players follow their pass.', 'Two touches.', NULL, 'Open up and receive on the first touch, pass on the second.', '8', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 560),
  ('Double triangle circuit with central one-two', 'passing_unopposed', 'unopposed', 'in_possession', 76, 76, 'Passing Combinations 13', 'Klopp (Liverpool)', 'Adding a one-two with the central player to the two-ball double triangle.', 'Same bow-tie double triangle with two balls starting at A and E.', 'A/E to B/F; B/F diagonally to C/G who drop; C/G set back to B/F one touch; B/F move onto it and pass to D/H. Players follow their pass.', 'Central player one touch; others two touches.', 'After a period the coach changes the direction.', NULL, '8', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 570),
  ('Multi-direction passing square, open to support', 'passing_unopposed', 'unopposed', 'in_possession', 77, 77, 'Passing Combinations 14', 'Klopp (Liverpool)', 'Opening up on the half-turn and supporting from different directions.', 'Square with four numbered corner positions; players at corners and moving inside.', 'A dribbles in and passes diagonally to B, then moves to position 2; B plays outside to C who comes off the cone, receives on the half-turn (2 touches) and passes to D; D returns to C who finds B; B dribbles in and diagonally finds E, and so on around the square, with F receiving and finding A and E.', 'Two touches for half-turn receivers.', 'A second ball is added later.', 'Receive on the half-turn.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 580),
  ('Diagonal passes with left-right support movement', 'passing_unopposed', 'unopposed', 'in_possession', 78, 78, 'Passing Combinations 15', 'Klopp (Liverpool)', 'Constant support movement to either side of a mannequin to create passing angles.', 'Square with a central mannequin and mannequins near each corner; four players stay at their corners.', 'Players pass straight and diagonally in a set order (A diagonal to B''s left, B straight to C''s right, etc.), each moving continuously from one side of their mannequin to the other to receive.', 'All one touch; no rotation of positions.', NULL, 'Move early to show for the pass on the correct side.', '4', 4, 4, NULL, NULL, NULL, NULL, false, false, false, NULL, 590),
  ('Receive on half-turn and diagonal pass', 'passing_unopposed', 'unopposed', 'in_possession', 79, 79, 'Passing Combinations 16', 'Klopp (Liverpool)', 'Receiving on the half-turn, diagonal passing and timing a second ball.', 'Rectangle with A1 and A2 at the top corners, B1 and B2 on cones down the sides, C1 and C2 at the bottom.', 'A1 to B1 who checks, opens up and receives (2 touches) and passes diagonally to C1; C1 receives behind the cone and dribbles to A2. As C1 receives, A2 starts the mirror sequence to B2 and C2.', 'B two touches, C one touch to receive.', NULL, 'Quicker turns, speed up after the pass.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 600),
  ('Half-turn, diagonal pass and one-two', 'passing_unopposed', 'unopposed', 'in_possession', 80, 80, 'Passing Combinations 17', 'Klopp (Liverpool)', 'Adds a one-two to the half-turn diagonal pattern.', 'Same rectangle with A1/A2, B1/B2 and C1/C2.', 'A1 to B1 (half-turn), B1 diagonal to C1; C1 checks and plays into the area for B1''s diagonal run; B1 plays a weighted pass for C1 going round the cone; C1 dribbles to A2, who starts the mirror sequence on B1''s second pass.', NULL, NULL, 'Quick combination with good technique.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 610),
  ('Double one-two finishing in mini goal', 'passing_unopposed', 'unopposed', 'in_possession', 81, 81, 'Passing Combinations 18', 'Klopp (Liverpool)', 'Double one-two combination with a timed run, ending with a pass into a mini goal.', 'Rectangle with mini goals at the two bottom corners; A1/A2 by the goals, B1/B2 on side cones, C1/C2 at the top.', 'A1 to B1 who checks and drops; B1 back to A1; A1 diagonal to C1; C1 lays off for B1''s run round the cone; B1 passes across for C1''s timed run round the cone; C1 passes into the mini goal. As B1 hits C1, A2 starts the mirror sequence on the other side.', 'Players follow their pass.', NULL, 'Well-timed runs round the cone.', '6+', 6, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 620),
  ('Quick one-twos and switch, two-ball diamond', 'passing_unopposed', 'unopposed', 'in_possession', 82, 82, 'Passing Combinations 19', 'Klopp (Liverpool)', 'Quick one-twos, timing of support and switching the pass across.', 'Two connected triangles with central middle cones; players A, B, C (top), D, E, F; two balls start at A and D.', 'A/D pass to C/F coming off the middle cones; C/F set in front for A/D to run onto; A passes to C and D to F, who have moved across to the other side; C/F play in front of D/A who has moved on; continuous. Rotation A to B to C to D to E to F.', NULL, NULL, 'Go at the same time, quick one-two, tempo.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 630),
  ('Give-and-go and switch in two squares', 'passing_unopposed', 'unopposed', 'in_possession', 83, 83, 'Passing Combinations 20', 'Klopp (Liverpool)', 'Give-and-go into a long switch pass across two connected squares.', 'Long rectangle split into two connected squares with groups at the corners; two balls start at A1 and A2.', 'A1/A2 pass to C1/C2 who check off their cones; C passes to B (also checking); B plays into the area for A''s run; A plays a weighted long pass for C''s run; C passes to the next A and joins the opposite group.', 'Players rotate A to B to C to the opposite group.', 'Played clockwise and anti-clockwise.', NULL, '8+', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 640),
  ('Double square short one-twos, central support', 'passing_unopposed', 'unopposed', 'in_possession', 84, 84, 'Passing Combinations 21', 'Klopp (Liverpool)', 'Short one-twos and movement of central support players.', 'Two squares side by side with four middle players B1, C1, B2, C2 on cones and A/D players at the corners; two balls start at A1 and A2.', 'A to B and back; A to C who lays it for B; B to D who lays it for C; C plays in front of D to run onto; D passes to the opposite A and the sequence restarts. Middle players check off cones before receiving.', 'All one touch; players rotate A to B to C to D to opposite group.', 'Also played anti-clockwise.', 'Movement and speed of direction of the middle four.', '8+', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 650),
  ('Breaking lines with lay-offs and forward runs', 'passing_unopposed', 'unopposed', 'in_possession', 85, 85, 'Passing Combinations 22', 'Klopp (Liverpool)', 'Breaking lines with angled support, set-backs and forward runs past mannequins.', 'In the wide halves of the final third: two groups of 8 each working around blue mannequins at positions A, B, C, D; two balls start at A1 and A2.', 'A to B; B to C and returns to A; C sets back for A who has moved past the first mannequin; A to D; D sets back for A curving around the second mannequin; A passes to the A position of the other group and moves to D.', NULL, NULL, 'Create good angles to receive.', '8 per group', 8, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 660),
  ('Breaking lines with lay-offs and third-man run', 'passing_unopposed', 'unopposed', 'in_possession', 86, 86, 'Passing Combinations 23', 'Klopp (Liverpool)', 'Same line-breaking pattern finishing with a third-man return.', 'Same mannequin set-up with groups of 8 and two balls from A1 and A2.', 'A to B, B to C, C sets back for A past the first mannequin; A to D, D sets back for A curving round the second mannequin; A passes across to C who turns; C returns for A on the run; A passes to the other group''s A position.', NULL, NULL, 'Create good angles to receive.', '8 per group', 8, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 670),
  ('Box-mannequin passing with rotations, inside or outside', 'passing_unopposed', 'unopposed', 'in_possession', 87, 88, 'Passing Combinations 24', 'Klopp (Liverpool)', 'Support play with players choosing to receive inside or outside a box of mannequins.', 'Rectangle with four mannequins forming a central box; players A, B at the top, C, D on wide cones, E, F, G lower down.', 'Pattern 1: A to B; B finds C outside the box; C to D (who comes across); D sets back for B; B plays wide in front of the mannequin for E; E diagonal to F, F to G, G to D now outside, then D inside to C who sets for G or turns to B. Pattern 2: the same but the first receiver is positioned inside the box, with movements following each pass.', 'Players decide whether to move inside or outside first.', 'Lijnders adds one-two combinations.', NULL, '7+', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 680),
  ('Possession in end zone, switch with sprints', 'possession', 'unopposed', 'in_possession', 89, 89, 'Passing Combinations 25', 'Klopp (Liverpool)', 'Short possession through a rotating middle player then changing direction with a sprint to support.', 'Two end zones; five players with a ball in one zone and one player in the other.', 'The five pass through a constantly rotating middle player; after 15+ passes the ball goes to the free player in the far zone and all but one sprint across to support and repeat.', '15+ passes before the switch.', NULL, 'Changing direction was the difference in the last game.', '6', 6, 6, NULL, NULL, NULL, NULL, false, false, true, NULL, 690),
  ('Possession then whistle counter with new ball', 'transition', 'unopposed', 'to_attack', 90, 90, 'Passing Combinations 26', 'Klopp (Liverpool)', 'Reacting to a signal to break fast and score.', 'Seven cones near halfway each with a player; two mini goals on the edge of the box; coach with balls at the end line.', 'Players pass and rotate positions; on the whistle they leave their ball and a coach plays in a new ball from the end, and they launch a fast break to score in a mini goal.', NULL, NULL, 'Free decision-making in the combinations.', '7', 7, 7, NULL, NULL, NULL, NULL, true, false, true, NULL, 700),
  ('Possession then whistle counter with same ball', 'transition', 'unopposed', 'to_attack', 91, 91, 'Passing Combinations 27', 'Klopp (Liverpool)', 'Switching from passing to a quick attack with the ball in play.', 'Seven cones near halfway each with a player; two mini goals on the edge of the box.', 'Players pass and rotate; on the whistle they attack quickly with the same ball to score in one of the mini goals.', NULL, NULL, 'Free decision-making.', '7', 7, 7, NULL, NULL, NULL, NULL, true, false, true, NULL, 710),
  ('Diamond give-and-go, switch and through pass', 'passing_unopposed', 'unopposed', 'in_possession', 93, 93, 'Diamond Passing Combinations 1', 'Klopp (Liverpool)', 'Give-and-go, one-two and a through pass around a diamond with mannequins.', 'Diamond with mannequins/poles at B, C and D; players at A (two), B, C, D.', 'A to B and back; A plays for B''s run round the mannequin; B across to C coming round the pole; C to D and back; C plays for D around the mannequin; D dribbles back to start and A2 begins.', 'Players check off their cone before receiving; rotate A to B to C to D to A2.', NULL, NULL, '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 720),
  ('Diamond one-two, lay-offs and through pass', 'passing_unopposed', 'unopposed', 'in_possession', 94, 94, 'Diamond Passing Combinations 2', 'Klopp (Liverpool)', 'One-twos and lay-offs ending with a through pass round a mannequin.', 'Same diamond with mannequins at B, C and D.', 'A to B and back; A to C; C sets for B round the mannequin; B passes across the diamond to D; D sets for C round the mannequin; C plays the final pass for D''s run; D dribbles to start.', 'Check off cone; rotate A to B to C to D to A2.', NULL, NULL, '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 730),
  ('Diamond one-two, lay-off and switch pass', 'passing_unopposed', 'unopposed', 'in_possession', 95, 95, 'Diamond Passing Combinations 3', 'Klopp (Liverpool)', 'One-two and lay-off finishing with a long diagonal switch.', 'Same diamond with mannequins.', 'A to B and back; A to C; C sets for B round the mannequin; B plays a long diagonal (ground or aerial) to D running round the mannequin; D dribbles to start.', 'Check off cone; rotate A to B to C to D to A2.', NULL, NULL, '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 740),
  ('Diamond short combination and switch pass', 'passing_unopposed', 'unopposed', 'in_possession', 96, 96, 'Diamond Passing Combinations 4', 'Klopp (Liverpool)', 'Short combination play then a long diagonal switch.', 'Same diamond with mannequins.', 'A to B and back; A to C round the mannequin; C and B exchange short passes; C plays the long diagonal (ground or aerial) for D''s run round the mannequin; D dribbles to start.', 'Check off cone; rotate A to B to C to D to A2.', NULL, NULL, '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 750),
  ('Diamond one-two, pass, one-two, pass', 'passing_unopposed', 'unopposed', 'in_possession', 97, 97, 'Passing Diamond Combinations 5', 'Klopp (Liverpool)', 'Quick one-twos and timing of checking runs round a passing diamond.', 'Four cones form a diamond with a mannequin beside each wide and top point; A starts at the bottom with A2 queued behind, B on the right, C (with C2) at the top, D on the left. Spare balls at A.', 'A plays a one-two with B, then finds C, who has checked off his cone; C plays D and gets it back, then feeds D again as D bends round the mannequin; D passes to A2 to restart.', 'Mostly one touch on the sides, two touches at the top and at the restart.', NULL, 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '6+ players', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 760),
  ('Diamond one-two, give-and-go, third man run', 'passing_unopposed', 'unopposed', 'in_possession', 98, 98, 'Passing Diamond Combinations 6', 'Klopp (Liverpool)', 'Combining a one-two and a give-and-go before releasing a well-timed third-man run.', 'Four cones form a diamond with a mannequin beside each wide and top point; A starts at the bottom with A2 queued behind, B on the right, C (with C2) at the top, D on the left. Spare balls at A.', 'A and B combine, A finds C coming at an angle, C plays B round his mannequin, B squares it back to C (give-and-go), then C slips a timed pass for D running round the left mannequin; D plays A2.', 'One touch for B and C, two touches for A.', NULL, 'Final pass weighted to meet D''s run; check away before receiving.', '6+ players', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 770),
  ('Diamond one-two plus two give-and-goes', 'passing_unopposed', 'unopposed', 'in_possession', 99, 99, 'Passing Diamond Combinations 7', 'Klopp (Liverpool)', 'Linking a one-two with two give-and-goes on both sides of the diamond.', 'Four cones form a diamond with a mannequin beside each wide and top point; A starts at the bottom with A2 queued behind, B on the right, C (with C2) at the top, D on the left. Spare balls at A.', 'A-B one-two, A to C, C sends B round the mannequin and B returns it across to C; C plays D, D gives back to C, and C feeds D moving round the left mannequin; D passes to A2.', 'One touch for B and C, two for A.', NULL, 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '6+ players', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 780),
  ('Diamond one-two, lay-off, switch, give-and-go', 'passing_unopposed', 'unopposed', 'in_possession', 100, 100, 'Passing Diamond Combinations 8', 'Klopp (Liverpool)', 'Lay-offs and a switch of play across the diamond followed by a give-and-go.', 'Four cones form a diamond with a mannequin beside each wide and top point; A starts at the bottom with A2 queued behind, B on the right, C (with C2) at the top, D on the left. Spare balls at A.', 'A-B one-two, A to C, C plays B round the mannequin; B switches straight across to D, who lays it off to C coming round; C returns it to D as D spins round the mannequin, then D plays A2.', 'One touch for B and C, two for A.', NULL, 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '6+ players', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 790),
  ('Central link diamond: one-twos, open up', 'passing_unopposed', 'unopposed', 'in_possession', 101, 101, 'Passing Diamond Combinations 9', 'Klopp (Liverpool)', 'Using a central link player for one-twos and opening the body to carry the ball forward.', 'Diamond of cones with a pair of mannequins at each side point and single mannequins top and bottom; a central link player D stands in the middle, A (and A2) at the bottom, B right, C top, E left.', 'A plays into central D and gets it back round the mannequin, then A opens up and dribbles past the two mannequins before passing to B; B plays C at an angle, C sets for D, who returns it to C round the mannequin; C opens up, carries past the mannequins and plays E, who feeds A2.', NULL, NULL, 'Players rotate A to B to C to D to E; open the body before carrying.', '7+ players', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 800),
  ('Central link diamond: lay-offs and support', 'passing_unopposed', 'unopposed', 'in_possession', 102, 102, 'Passing Diamond Combinations 10', 'Klopp (Liverpool)', 'Lay-offs and support play through a central link player on both sides.', 'Diamond of cones with a pair of mannequins at each side point and single mannequins top and bottom; a central link player D stands in the middle, A (and A2) at the bottom, B right, C top, E left.', 'A-D one-two round the mannequin, A plays B, B plays inside to D, D returns it to B going round the pair of mannequins; B to C, C sets for D, D passes across to E, E sets for C coming round the mannequin, and C plays A2.', NULL, NULL, 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '7+ players', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 810),
  ('Central link diamond: support for give-and-goes', 'passing_unopposed', 'unopposed', 'in_possession', 103, 103, 'Passing Diamond Combinations 11', 'Klopp (Liverpool)', 'Supporting angles from the link player to set up give-and-goes.', 'Diamond of cones with a pair of mannequins at each side point and single mannequins top and bottom; a central link player D stands in the middle, A (and A2) at the bottom, B right, C top, E left.', 'A-D one-two, A to C, C sets for D turning, D plays C round the mannequin, C to E, E passes inside to D who has shifted across in support, D sends E round the two mannequins, E plays A2.', NULL, NULL, 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '7+ players', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 820),
  ('Central link diamond: support left or right', 'passing_unopposed', 'unopposed', 'in_possession', 104, 104, 'Passing Diamond Combinations 12', 'Klopp (Liverpool)', 'Reading which side to support from and choosing between two set-up options.', 'Diamond of cones with a pair of mannequins at each side point and single mannequins top and bottom; a central link player D stands in the middle, A (and A2) at the bottom, B right, C top, E left.', 'A-D one-two, A to C, C sets for D, D plays B round the two mannequins, C passes across the diamond to E, E sets for either D or C, who returns it to E running round the two mannequins; E plays A2.', NULL, 'Option a: E sets for D; option b: E sets for C.', 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '7+ players', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 830),
  ('Diamond plus triangle, quick changes of direction', 'passing_unopposed', 'unopposed', 'in_possession', 105, 105, 'Passing Diamond Combinations 13', 'Klopp (Liverpool)', 'Fast changes of direction and switches across a diamond with an inside triangle.', 'Diamond of cones and mannequins with an extra inside triangle point: A at the bottom, B right, C top, D at a yellow mannequin top-left and E just inside the diamond.', 'A-B one-two with A stepping forward, A to C, C finds E moving inside, E switches back across to B round the mannequin, B plays across to D dropping off the yellow mannequin, D slides the final ball for E running outside and round the mannequin, and E dribbles to A''s spot to restart.', NULL, NULL, 'Everyone checks away from the cone before showing to receive; players follow the ball round the diamond to the next position.', '5+ players', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 840),
  ('Diamond plus triangle, short quick combinations', 'passing_unopposed', 'unopposed', 'in_possession', 106, 106, 'Passing Diamond Combinations 14', 'Klopp (Liverpool)', 'Short, quick combination play and a forward release, as when beating a press.', 'Diamond of cones and mannequins with an extra inside triangle point: A at the bottom, B right, C top, D at a yellow mannequin top-left and E just inside the diamond.', 'A-B one-two, A to C, C plays B round the mannequin, E (via the switch) plays across the diamond to D dropping off the yellow mannequin, D sets to C shifting in front of the mannequin, C to E, E sets for D, D plays the final ball for E round the mannequin, and E dribbles to A''s spot to restart.', NULL, NULL, 'Coach cue: under pressure go short-short then forward (''tick, tick, boom'').', '5+ players', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 850),
  ('4v2 rondo, free player and closing lines', 'rondo', 'opposed', 'in_possession', 113, 113, 'Pressing Rondos and Possession Games 1', 'Klopp (Liverpool)', 'Breaking pressure to find the free player, while the two defenders press as a pair to shut passing lines.', 'Groups of 6 in an 8 yard square: one attacker on each side (staying inside the area), two defenders in the middle.', 'The four outside players keep the ball; the two middle players press together, cutting angles to win it.', 'Outside players one touch; whoever loses the ball swaps with the defender who won it.', NULL, 'Count passes aloud to keep the competition sharp.', '4v2', 6, 6, '8 x 8 yards', 7.3, 7.3, NULL, false, false, false, NULL, 860),
  ('4v2 pressing rondo plus floating middle player', 'rondo', 'overload', 'in_possession', 114, 114, 'Pressing Rondos and Possession Games 2', 'Klopp (Liverpool)', 'Keeping the ball with help from a central floater while two defenders press together.', 'Square with one attacker on each side and a yellow floating player in the middle helping them, plus two defenders.', 'Four outside players plus the floater keep possession; the two defenders press and close passing lines.', 'Outside players one touch, floater two touches; when the ball is lost the last two players to touch it swap with the defenders.', NULL, 'Set a target number of passes and celebrate reaching it; keep making new triangles and know where the free player is.', '4(+1)v2', 7, 7, NULL, NULL, NULL, NULL, false, false, false, NULL, 870),
  ('5v2 rondo: win it within 6 passes', 'rondo', 'opposed', 'out_of_possession', 115, 115, 'Pressing Rondos and Possession Games 3', 'Klopp (Liverpool)', 'Intense pair pressing with the goal of regaining the ball inside six passes.', 'Groups of 7 in a 10 yard square: five outside players, two defenders inside.', 'The five keep the ball one touch; the two defenders press together and close angles to win it.', 'One touch. Win it within the first 6 passes and BOTH defenders swap out; after 6 passes only the player who lost it swaps with the winner.', NULL, 'The 6-pass target lifts the speed and intensity of the press.', '5v2', 7, 7, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 880),
  ('Simultaneous 5v2 rondos with sprint to new square', 'transition', 'opposed', 'to_defend', 116, 116, 'Pressing Rondos and Possession Games 4', 'Klopp (Liverpool)', 'Reacting instantly after a regain: defenders sprint to press in another group.', 'Several squares (4 in the session) side by side; most play a 5v2 rondo, one group has 5 players and no defenders.', 'Normal 5v2 rondos run in each square; the 5v0 group just pass and wait. When a defending pair win the ball for a second time, two outside players from the group without defenders sprint to that square to defend, and the pair who won it swap roles; the new defenders must win the ball twice in their square before switching again.', 'Two regains before the defenders change roles.', NULL, NULL, 'Groups of 5v2 plus a 5v0 group', 19, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 890),
  ('6v2 rondo, free player and closing lines', 'rondo', 'opposed', 'in_possession', 117, 117, 'Pressing Rondos and Possession Games 5', 'Klopp (Liverpool)', 'Finding the free player through quick passing while two defenders cut passing lanes.', 'Groups of 8 in a 10 yard square: two attackers on two sides, one on the other two (all staying inside), two defenders.', 'The six outside players keep the ball; the two inside players press together to win it.', 'One touch; the player who loses it swaps with the defender who won it.', NULL, 'Keep count of passes.', '6v2', 8, 8, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 900),
  ('6v2 end to end rondo with constant pressing', 'rondo', 'opposed', 'in_possession', 118, 118, 'Pressing Rondos and Possession Games 6', 'Klopp (Liverpool)', 'Moving the ball end to end through support play while two defenders keep shifting to press.', 'Groups of 8 in a 5 x 15 yard area: two attackers on each long side, one at each end, two defenders inside.', 'The six outsiders move the ball from one end player to the other; side players keep moving to offer angles. Defenders press, and if the ball reaches the far end they sprint across to press again.', 'One touch; the player who loses it swaps with the one who wins it.', NULL, 'Side players constantly move up and down to support the ends.', '6v2', 8, 8, '5 x 15 yards', 13.7, 4.6, NULL, false, false, true, NULL, 910),
  ('4-team 2+2+2v2 rondo with fast transitions', 'rondo', 'opposed', 'to_defend', 119, 119, 'Pressing Rondos and Possession Games 7', 'Klopp (Liverpool)', 'Team-based pressing in pairs and quick role changes after a regain.', 'Groups of 8 (four pairs) in a 10 yard square: two players on two sides, one on the other two, one pair defending inside.', 'Three pairs on the outside keep the ball one touch; the inside pair press together.', 'One touch. When the defending pair win it they swap out with the pair that lost it, which becomes the new middle pair.', NULL, NULL, '2+2+2v2', 8, 8, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 920),
  ('7v7 pole gates possession game', 'positional_game', 'opposed', 'in_possession', 120, 120, 'Pressing Rondos and Possession Games 8', 'Klopp (Liverpool)', 'Keeping the ball and scoring by passing through gates while the other team presses.', 'Rectangle with several pole gates spread around it; two teams of 7.', 'One team keeps the ball and scores by passing through any gate to a teammate who receives it on the other side; the defending team presses to win it, then they swap roles.', 'A completed pass and receive through a gate is a goal; most goals wins.', NULL, NULL, '7v7', 14, 14, NULL, NULL, NULL, NULL, false, false, true, NULL, 930),
  ('7v7 pole gates game with end zone players', 'positional_game', 'opposed', 'in_possession', 121, 121, 'Pressing Rondos and Possession Games 9', 'Klopp (Liverpool)', 'Gate possession game with an extra outlet in each end zone to stretch play.', 'As the 7v7 pole gates game, plus a marked end zone at each end holding one player from each team; nobody else may enter the zones.', 'Team in possession scores by passing through a gate to a receiving teammate, using its end-zone players as outlets; defenders press and swap roles when they win it.', 'Gate pass and receive = goal; only the designated player may be in each end zone.', NULL, NULL, '7v7', 14, 14, NULL, NULL, NULL, NULL, false, false, true, NULL, 940),
  ('Hunt the ball 3(+3)v3 counter-press rondo', 'transition', 'overload', 'to_defend', 124, 124, 'Pressing and Counter-pressing Rondos and Possession Games 1', 'Klopp (Liverpool)', 'Relentless pressing in a triangle and immediate counter-pressing after losing the ball.', '12 yard square, three teams of three: three reds on the outside and two whites outside plus one white in the middle, against three yellow defenders inside.', 'Reds and whites keep the ball; the three yellows hunt it in a triangle shape. If a red or white loses it, his whole colour swaps roles with the yellows and must press the new ball carrier at once.', 'Losing colour (all 3) becomes the defending trio.', NULL, 'React instantly to press the new ball carrier; press as a compact triangle.', '3(+3)v3', 9, 9, '12 x 12 yards', 11.0, 11.0, NULL, false, false, false, NULL, 950),
  ('High intensity 3(+2)v3 pressing possession game', 'transition', 'overload', 'to_defend', 125, 125, 'Pressing and Counter-pressing Rondos and Possession Games 2', 'Klopp (Liverpool)', 'High intensity pressing by three defenders and instant counter-press by the team that loses it.', '12 yard square: two teams of three plus two yellow jokers who join the team in possession.', 'Team in possession plus jokers keep the ball with quick movement; the three defenders press, block lines and try to win it, then swap roles while the losing team counter-presses straight away.', 'Free movement, mostly one or two touches.', NULL, 'Defenders press hard; attackers use the space and good support to keep it.', '3(+2)v3', 8, 8, '12 x 12 yards', 11.0, 11.0, NULL, false, false, false, NULL, 960),
  ('4(+2)v4 pressing possession game, end to end', 'transition', 'overload', 'to_defend', 126, 126, 'Pressing and Counter-pressing Rondos and Possession Games 3', 'Klopp (Liverpool)', 'Playing through the press from one end to the free man at the other, and counter-pressing on loss.', '15 x 20 yard area, two teams of four plus two yellow jokers (at the ends) who play for the team in possession.', 'Team in possession plus jokers try to break pressure and move the ball end to end; the four defenders press as a unit and swap roles when they win it, with the losing team counter-pressing.', 'Free movement, mostly one or two touches.', NULL, 'Quality passing and support; chase it back immediately.', '4(+2)v4', 10, 10, '15 x 20 yards', 18.3, 13.7, NULL, false, false, true, NULL, 970),
  ('4(+2)v4 small-area intense counter-press game', 'transition', 'overload', 'to_defend', 127, 127, 'Pressing and Counter-pressing Rondos and Possession Games 4', 'Klopp (Liverpool)', 'More frequent turnovers in a tight area to drill immediate counter-pressing.', '5 x 10 yard area, two teams of four plus two jokers with the team in possession.', 'Same as the 15 x 20 version: keep the ball with the jokers, defenders press and swap on a regain, the team that lost it counter-presses at once.', 'Mostly one touch.', NULL, 'Smaller space means harder to keep it and more chances to win it back straight after losing it.', '4(+2)v4', 10, 10, '5 x 10 yards', 9.1, 4.6, NULL, false, false, false, NULL, 980),
  ('3(+2)v3(+2) possession with free outside supporters', 'transition', 'overload', 'to_defend', 128, 128, 'Pressing and Counter-pressing Rondos and Possession Games 5', 'Klopp (Liverpool)', 'Using always-free outside support players to keep the ball, and counter-pressing when it is lost.', '10 yard square with outside channels; two teams of five, three of each inside and two of each outside.', 'One team keeps the ball using its outside players; the other team''s inside three press. On a regain the teams swap and the losers counter-press.', 'Each team''s outside players only help their own team.', NULL, 'Use the outside players: they are always free to receive.', '3(+2)v3(+2)', 10, 10, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 990),
  ('4(+2)v4 pressing game in the centre circle', 'transition', 'overload', 'to_defend', 129, 129, 'Pressing and Counter-pressing Rondos and Possession Games 6', 'Klopp (Liverpool)', 'High intensity pressing and counter-pressing in a circular space.', 'Centre circle (10 yard radius); two teams of four plus two yellow jokers with the team in possession.', 'Team in possession plus jokers keep the ball; the four defenders press and block lines, then swap roles on a regain while the losers counter-press.', 'Free movement, mostly one or two touches.', NULL, NULL, '4(+2)v4', 10, 10, 'Circle, 10 yard radius', 18.3, 18.3, NULL, false, false, false, NULL, 1000),
  ('4(+3)v4 pressing game in the centre circle', 'transition', 'overload', 'to_defend', 130, 130, 'Pressing and Counter-pressing Rondos and Possession Games 7', 'Klopp (Liverpool)', 'Centre circle press and counter-press with a bigger joker overload.', 'Centre circle (10 yard radius); two teams of four plus three jokers with the team in possession.', 'As the 4(+2)v4 centre circle game with one more joker.', 'Free movement, mostly one or two touches.', NULL, 'Counter-press collectively to win it back the moment it is lost.', '4(+3)v4', 11, 11, 'Circle, 10 yard radius', 18.3, 18.3, NULL, false, false, false, NULL, 1010),
  ('4(+6)v4 hexagon possession game', 'transition', 'overload', 'to_defend', 131, 131, 'Pressing and Counter-pressing Rondos and Possession Games 8', 'Klopp (Liverpool)', 'Supporting with a big overload and continuous pressing by an outnumbered unit.', 'Hexagon marked with poles; two teams of four inside plus six yellow players on the outside who play for the team in possession.', 'The team in possession keeps the ball 10v4, moving it quickly so the four defenders must keep pressing; on a regain the teams swap and the losers counter-press.', 'Inside players mostly one or two touches; outside players one touch.', NULL, 'Tiring for defenders: keep pressing continuously.', '4(+6)v4', 14, 14, NULL, NULL, NULL, NULL, false, false, false, NULL, 1020),
  ('3-team 4(+4)v4 pressing possession game', 'transition', 'overload', 'to_defend', 132, 132, 'Pressing and Counter-pressing Rondos and Possession Games 9', 'Klopp (Liverpool)', 'Keeping an 8v4 overload in triangles and compressing quickly to counter-press after a loss.', '10 yard square, three teams of four; two teams in possession each have three outside and one inside, the third team defends with all four inside.', 'The two possession teams keep the ball; the defenders press. When the defenders win it they swap roles with the team that lost it, which must counter-press immediately.', 'Mostly one or two touches.', NULL, 'Make triangles in possession; outside players squeeze in quickly to win it back.', '4(+4)v4', 12, 12, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 1030),
  ('4v4v4 three-zone end to end game', 'transition', 'opposed', 'to_defend', 133, 133, 'Pressing and Counter-pressing Rondos and Possession Games 10', 'Klopp (Liverpool)', 'Moving the ball through a middle zone and counter-pressing as a fast transition after a turnover.', '10 x 15 yard area with a 2 yard central zone; three teams of four, one team in each end zone and the defending team split two in the end zone and two in the middle.', 'The team in an end zone (4v2) tries to pass through to the team at the far end; two defenders press in the end zone and two try to intercept in the middle. If the defenders win it, they swap with the team that lost it and pass to the far team; two of the losing team drop into the middle and two sprint to press in the far zone.', 'Continuous; ball must reach the opposite end team.', NULL, NULL, '4v4v4', 12, 12, '10 x 15 yards', 13.7, 9.1, NULL, false, false, true, NULL, 1040),
  ('4(+3)v4 positional possession game', 'transition', 'overload', 'to_defend', 134, 134, 'Pressing and Counter-pressing Rondos and Possession Games 11', 'Klopp (Liverpool)', 'Positional possession on the outside and immediate counter-press after the ball is lost.', '10 x 15 yard area; two teams of four plus three jokers (one at each end, one inside). Team in possession sets two players on each long side; the other team starts inside.', 'The outside team keeps the ball with the jokers; the inside team press to win it. On a regain they move to the outsides and the team that lost it moves inside to counter-press at once.', NULL, NULL, 'Go and get it back, don''t stop.', '4(+3)v4', 11, 11, '10 x 15 yards', 13.7, 9.1, NULL, false, false, false, NULL, 1050),
  ('4(+4)v4 positional possession game', 'transition', 'overload', 'to_defend', 135, 135, 'Pressing and Counter-pressing Rondos and Possession Games 12', 'Klopp (Liverpool)', 'Same positional press and counter-press game with a fourth joker for a bigger overload.', 'As the 4(+3)v4 positional game (10 x 15 yards) with one more joker added.', 'Outside team keeps the ball with four jokers; inside team press and swap on a regain, then the losers counter-press.', NULL, NULL, 'Act together to win the ball back straight after losing it.', '4(+4)v4', 12, 12, '10 x 15 yards', 13.7, 9.1, NULL, false, false, false, NULL, 1060),
  ('7(+3)v7 positional possession game', 'transition', 'overload', 'to_defend', 136, 136, 'Pressing and Counter-pressing Rondos and Possession Games 13', 'Klopp (Liverpool)', 'Positional possession by match positions and collective counter-pressing on loss.', '25 x 30 yard area; two teams of seven plus three jokers playing for the team in possession. Positions: centre backs on the base line, forward at the top, wide players on the sides, jokers as central midfielders.', 'One team keeps the ball in its positional shape with the jokers; the other presses inside. On a regain the teams swap: winners spread to the positions, losers counter-press at once.', NULL, NULL, NULL, '7(+3)v7', 17, 17, '25 x 30 yards', 27.4, 22.9, NULL, false, false, false, NULL, 1070)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'jurgen-klopp-102-passing-counter-pressing-possession-games-speed-warm-ups-direct') b;
INSERT INTO schema_migrations (filename) VALUES ('2904-exercises-book-jurgen-klopp-102-passing-counter-pressing-possession-games-s.sql') ON CONFLICT DO NOTHING;
COMMIT;
